                    String gameIdArg = invocation.getArgument(0);
                    String playerIdArg = invocation.getArgument(1);
                    double latArg = invocation.getArgument(2);
                    double lonArg = invocation.getArgument(3);
                    long timeArg = invocation.getArgument(4);
